using System;using System.IO;using System.Linq;using System.Collections;using System.Collections.Generic;using System.Runtime.InteropServices;using System.Web.Script.Serialization;using LabVIEWAutomation;
public static class TypedefWorker {
 static JavaScriptSerializer J=new JavaScriptSerializer(){MaxJsonLength=6000000};
 static Dictionary<string,object> Obj(object o){return (Dictionary<string,object>)o;}
 static object[] Arr(object o){return o==null?new object[0]:((IEnumerable)o).Cast<object>().ToArray();}
 static string S(object o){return Convert.ToString(o);}
 static void Check(VirtualInstrument v){if(Convert.ToBoolean(v.GetControlValue("Error"))||Convert.ToInt32(v.GetControlValue("Code"))!=0)throw new Exception("Helper error code="+v.GetControlValue("Code")+" source="+v.GetControlValue("Source"));}
 public static string DiagnoseJson(string tools){Application app=new Application();VirtualInstrument d=null;try{d=app.GetVIReference(Path.Combine(tools,"ReadVIErrors.vi"),"",false,0);var rows=new List<object>();foreach(string name in new[]{"InspectStateTypes","InspectStateConstants"}){var v=app.GetVIReference(Path.Combine(tools,name+".vi"),"",false,0);d.SetControlValue("vi path",Path.Combine(tools,name+".vi"));d.Run(false);rows.Add(new{name=name,state=Convert.ToInt32(v.ExecState),errors=d.GetControlValue("errors xml"),details=d.GetControlValue("details xml")});Marshal.ReleaseComObject(v);}return J.Serialize(rows);}finally{if(d!=null)Marshal.ReleaseComObject(d);Marshal.ReleaseComObject(app);}}
 public static string ValidateJson(string dir,string tools,string request){Application app=new Application();VirtualInstrument helper=null;try{var req=Obj(J.DeserializeObject(request));helper=app.GetVIReference(Path.Combine(tools,"ReadVIErrors.vi"),"",false,0);var files=new[]{S(req["filename"])}.Concat(Arr(req["module_files"]).Select(f=>"Modules/"+S(f)));var rows=new List<object>();foreach(string file in files){VirtualInstrument v=null;try{string full=Path.Combine(dir,file).Replace('/','\\');v=app.GetVIReference(full,"",false,0);int state=Convert.ToInt32(v.ExecState);helper.SetControlValue("vi path",full);helper.Run(false);var match=System.Text.RegularExpressions.Regex.Match(S(helper.GetControlValue("errors xml")),@"<Dimsize>(\d+)</Dimsize>");int count=match.Success?Int32.Parse(match.Groups[1].Value):-1;int code=Convert.ToInt32(helper.GetControlValue("get errors code"));if(state!=1||count!=0||code!=0)throw new Exception("VI compile gate failed "+file+" state="+state+" errors="+count+" code="+code+" "+S(helper.GetControlValue("errors xml")));rows.Add(new{file=file,execution_state=state,compiler_errors=count,get_errors_code=code});}finally{if(v!=null)Marshal.ReleaseComObject(v);}}return J.Serialize(rows);}finally{if(helper!=null)Marshal.ReleaseComObject(helper);Marshal.ReleaseComObject(app);}}
 public static string PrepareJson(string dir,string tools,string request){
  Application app=null;var helpers=new Dictionary<string,VirtualInstrument>();string stage="start";
  try{
   app=new Application();var req=Obj(J.DeserializeObject(request));var m=Obj(req["typedef_manifest"]);var types=Obj(m["types"]);var bindings=Arr(m["bindings"]);var created=new List<object>();var bound=new List<object>();var census=new List<object>();
   Func<string,VirtualInstrument> get=(name)=>{if(!helpers.ContainsKey(name))helpers[name]=app.GetVIReference(Path.Combine(tools,name+".vi"),"",false,0);var hv=helpers[name];if(hv.ExecState==ExecStateEnum.eBad){VirtualInstrument d=null;try{d=app.GetVIReference(Path.Combine(tools,"ReadVIErrors.vi"),"",false,0);d.SetControlValue("vi path",Path.Combine(tools,name+".vi"));d.Run(false);throw new Exception("Helper not executable "+name+": "+System.Text.RegularExpressions.Regex.Replace(S(d.GetControlValue("errors xml")),"<[^>]+>"," ")+" DETAILS: "+System.Text.RegularExpressions.Regex.Replace(S(d.GetControlValue("details xml")),"<[^>]+>"," "));}finally{if(d!=null)Marshal.ReleaseComObject(d);}}return hv;};
   foreach(var entry in types){stage="create "+entry.Key;var t=Obj(entry.Value);var v=get("CreateStateTypedef");v.SetControlValue("carrier path",Path.Combine(dir,"Types",S(t["carrier"])));v.SetControlValue("ctl path",Path.Combine(dir,"Types",S(t["file"])));v.SetControlValue("kind",(ushort)2);v.Run(false);
    int kind=Convert.ToInt32(v.GetControlValue("kind after save")),code=Convert.ToInt32(v.GetControlValue("code"));if(Convert.ToBoolean(v.GetControlValue("status"))||code!=0||kind!=2)throw new Exception("Native creation failed code="+code+" kind="+kind+" source="+v.GetControlValue("source"));created.Add(new{name=entry.Key,file=t["file"],control_vi_type=kind});
   }
   var nested=m.ContainsKey("nested_bindings")?Arr(m["nested_bindings"]):new object[0];var nestedChecks=new List<object>();var nestedPropagation=new List<object>();
   foreach(var item in nested){var n=Obj(item);stage="bind nested "+S(n["field"]);var parent=Obj(types[S(n["parent"])]);var child=Obj(types[S(n["typedef"])]);var v=get("BindNestedStateControl");v.SetControlValue("TargetPath",Path.Combine(dir,"Types",S(parent["file"])));v.SetControlValue("ObjectName",S(n["field"]));v.SetControlValue("TypedefPath",Path.Combine(dir,"Types",S(child["file"])));v.Run(false);Check(v);if(Convert.ToInt32(v.GetControlValue("BoundCount"))!=1||Arr(v.GetControlValue("ReplaceCodes")).Any(c=>Convert.ToInt32(c)!=0))throw new Exception("Nested typedef replacement failed");}
   foreach(object item in bindings){var b=Obj(item);stage="bind "+S(b["file"])+":"+S(b["object"]);bool constant=Convert.ToBoolean(b["constant"]);var v=get(constant?"BindStateConstant":"BindStateControl");var t=Obj(types[S(b["typedef"])]);v.SetControlValue("TargetPath",Path.Combine(dir,S(b["file"])).Replace('/','\\'));v.SetControlValue("ObjectName",S(b["object"]));v.SetControlValue("TypedefPath",Path.Combine(dir,"Types",S(t["file"])));v.Run(false);if(Convert.ToBoolean(v.GetControlValue("Error")))throw new Exception("Bind code="+v.GetControlValue("Code")+" source="+v.GetControlValue("Source")+" count="+v.GetControlValue("BoundCount")+" replace="+J.Serialize(v.GetControlValue("ReplaceCodes")));Check(v);int count=Convert.ToInt32(v.GetControlValue("BoundCount"));if(count==0){v.Run(false);Check(v);count=Convert.ToInt32(v.GetControlValue("BoundCount"));}if(count!=1)throw new Exception("Replacement count="+count);foreach(object c in Arr(v.GetControlValue("ReplaceCodes")))if(Convert.ToInt32(c)!=0)throw new Exception("Replace error="+c);bound.Add(new{file=b["file"],name=b["object"],count=count});}
   foreach(object item in bindings){var b=Obj(item);stage="inspect "+S(b["file"])+":"+S(b["object"]);bool constant=Convert.ToBoolean(b["constant"]);var v=get(constant?"InspectStateConstants":"InspectStateTypes");var t=Obj(types[S(b["typedef"])]);v.SetControlValue("TargetPath",Path.Combine(dir,S(b["file"])).Replace('/','\\'));v.Run(false);Check(v);var names=Arr(v.GetControlValue("Names")).Select(S).ToArray();var kinds=Arr(v.GetControlValue("Kinds"));var paths=Arr(v.GetControlValue("Paths")).Select(S).ToArray();var fields=Arr(v.GetControlValue("Fields")).Select(S).ToArray();int i=Array.IndexOf(names,S(b["object"]));if(i<0)throw new Exception("Missing name; saw "+String.Join(",",names));string expected=Path.Combine(dir,"Types",S(t["file"]));if(Convert.ToInt32(kinds[i])!=1||!String.Equals(paths[i],expected,StringComparison.OrdinalIgnoreCase))throw new Exception("Actual link kind="+kinds[i]+" path="+paths[i]);var actual=fields[i].Trim().Split('|');var expectedFields=Arr(t["fields"]).Select(x=>S(Obj(x)["name"])).ToArray();if(!actual.SequenceEqual(expectedFields))throw new Exception("Fields differ: "+String.Join("|",actual));census.Add(new{file=b["file"],name=b["object"],kind=kinds[i],path=paths[i],fields=actual,constant=constant});}
   // Native propagation proof: change ONLY .ctl, inspect dependents, restore before GUI tests.
   object propagation=null;var appType=Obj(types["ApplicationState"]);var stateBindings=bindings.Select(Obj).Where(b=>S(b["typedef"])=="ApplicationState").ToArray();string original= S(Obj(Arr(appType["fields"]).Last())["name"]), temporary=original+"_PropagationProbe";string ctlPath=Path.Combine(dir,"Types",S(appType["file"]));var rename=get("RenameTypedefField");bool edited=false;var propagated=new List<object>();
   Action<string,string> change=(from,to)=>{rename.SetControlValue("TargetPath",ctlPath);rename.SetControlValue("FieldName",from);rename.SetControlValue("NewFieldName",to);rename.Run(false);Check(rename);if(Convert.ToInt32(rename.GetControlValue("FieldIndex"))<0)throw new Exception("Propagation field not found");};
   try{
    stage="native propagation .ctl edit";change(original,temporary);edited=true;
    foreach(var b in stateBindings){stage="native propagation inspect "+S(b["file"])+":"+S(b["object"]);var v=get(Convert.ToBoolean(b["constant"])?"InspectStateConstants":"InspectStateTypes");v.SetControlValue("TargetPath",Path.Combine(dir,S(b["file"])).Replace('/','\\'));v.Run(false);Check(v);var names=Arr(v.GetControlValue("Names")).Select(S).ToArray();int i=Array.IndexOf(names,S(b["object"]));var fields=Arr(v.GetControlValue("Fields")).Select(S).ToArray();if(i<0||!fields[i].Contains(temporary)||fields[i].Trim().Split('|').Contains(original))throw new Exception("Typedef edit did not propagate");propagated.Add(new{file=b["file"],name=b["object"],fields=fields[i].Trim().Split('|')});}
   }finally{if(edited){stage="restore propagation field";change(temporary,original);}}
   foreach(var b in stateBindings){var v=get(Convert.ToBoolean(b["constant"])?"InspectStateConstants":"InspectStateTypes");v.SetControlValue("TargetPath",Path.Combine(dir,S(b["file"])).Replace('/','\\'));v.Run(false);Check(v);var names=Arr(v.GetControlValue("Names")).Select(S).ToArray();int i=Array.IndexOf(names,S(b["object"]));var fields=Arr(v.GetControlValue("Fields")).Select(S).ToArray();if(i<0||!fields[i].Trim().Split('|').Contains(original)||fields[i].Contains(temporary))throw new Exception("Typedef field was not restored");}
   foreach(string f in stateBindings.Select(b=>S(b["file"])).Distinct()){VirtualInstrument v=null;try{v=app.GetVIReference(Path.Combine(dir,f).Replace('/','\\'),"",false,0);v.SaveInstrument(Path.Combine(dir,f).Replace('/','\\'),false,false);}finally{if(v!=null)Marshal.ReleaseComObject(v);}}
   propagation=new{definition=ctlPath,original_field=original,temporary_field=temporary,consumer_regeneration=false,propagated_checks=propagated,restored=true};
   foreach(var item in nested){var n=Obj(item);var parent=Obj(types[S(n["parent"])]);var child=Obj(types[S(n["typedef"])]);var targets=bindings.Select(Obj).Where(b=>S(b["typedef"])==S(n["parent"])).ToList();targets.Add(new Dictionary<string,object>{{"file","Types/"+S(parent["file"])},{"object",S(n["parent"])},{"constant",false}});
    Func<Dictionary<string,object>,string[],object> inspect=(b,expectedFields)=>{var v=get(Convert.ToBoolean(b["constant"])?"InspectNestedConstant":"InspectNestedControl");v.SetControlValue("TargetPath",Path.Combine(dir,S(b["file"])).Replace('/','\\'));v.SetControlValue("ObjectName",S(b["object"]));v.SetControlValue("GroupName",S(n["field"]));v.Run(false);Check(v);string expectedPath=Path.Combine(dir,"Types",S(child["file"]));var actual=Arr(v.GetControlValue("Fields")).Select(S).ToArray();if(Convert.ToInt32(v.GetControlValue("Kind"))!=1||!String.Equals(S(v.GetControlValue("Path")),expectedPath,StringComparison.OrdinalIgnoreCase)||!actual.SequenceEqual(expectedFields))throw new Exception("Nested link/fields differ: "+S(b["file"])+":"+S(b["object"]));return new{file=b["file"],name=b["object"],field=n["field"],path=v.GetControlValue("Path"),kind=v.GetControlValue("Kind"),fields=actual};};
    var names=Arr(child["fields"]).Select(f=>S(Obj(f)["name"])).ToArray();foreach(var b in targets){stage="inspect nested "+S(b["file"]);nestedChecks.Add(inspect(b,names));}
    string old=names.Last(),temp=old+"_NestedPropagationProbe",childPath=Path.Combine(dir,"Types",S(child["file"]));bool changed=false;var edits=new List<object>();Action<string,string> edit=(from,to)=>{rename.SetControlValue("TargetPath",childPath);rename.SetControlValue("FieldName",from);rename.SetControlValue("NewFieldName",to);rename.Run(false);Check(rename);if(Convert.ToInt32(rename.GetControlValue("FieldIndex"))<0)throw new Exception("Child field not found");};
    try{stage="nested propagation edit child .ctl";edit(old,temp);changed=true;var renamed=names.Select(k=>k==old?temp:k).ToArray();foreach(var b in targets){stage="nested propagation inspect "+S(b["file"]);edits.Add(inspect(b,renamed));}}
    finally{if(changed){stage="restore nested field";edit(temp,old);}}
    foreach(var b in targets)inspect(b,names);nestedPropagation.Add(new{child_definition=childPath,field_before=old,temporary_field=temp,consumer_regeneration=false,checks=edits,restored=true});
    foreach(var b in targets){VirtualInstrument v=null;try{string file=Path.Combine(dir,S(b["file"])).Replace('/','\\');v=app.GetVIReference(file,"",false,0);v.SaveInstrument(file,false,false);}finally{if(v!=null)Marshal.ReleaseComObject(v);}}
   }
   return J.Serialize(new{created=created,bindings=bound,identity_checks=census,propagation_probe=propagation,nested_identity_checks=nestedChecks,nested_propagation=nestedPropagation});
  }catch(Exception e){throw new Exception(stage+": "+e.Message,e);}finally{foreach(var v in helpers.Values)Marshal.ReleaseComObject(v);if(app!=null)Marshal.ReleaseComObject(app);}
 }
}
